/**
 * M3.5 Pencil recognition: ovals → ellipse (only when clearly not round), smooth strokes →
 * spline through a few evenly spaced points (ends included); circles, arcs and polylines stay as
 * before. Uses the seeded pen model (strokes.ts) and frozen stroke fixtures
 * (fixtures/m35-strokes.json, generated by that pen model at 120 Hz and committed so they don't
 * drift with it).
 * SPDX-License-Identifier: GPL-3.0-or-later
 */

import type { StrokeSample, Vec2 } from '@wren-cad/contracts';
import { describe, expect, it } from 'vitest';
import { recognizeStroke, strokeFragment } from '../src/recognize';
import fixtures from './fixtures/m35-strokes.json';
import { core } from './helpers';
import {
  type Generated,
  genArc,
  genBlob,
  genCircle,
  genEllipse,
  genPolyline,
  genTriangle,
  genWave,
  genZigzag,
  SHAKY,
  seeded,
  withPen,
} from './strokes';

const recognize = (s: readonly StrokeSample[]) => recognizeStroke(s, { tolerance: 3 });
const d = (a: Vec2, b: Vec2) => Math.hypot(a[0] - b[0], a[1] - b[1]);
/** Axis directions are equal modulo π. */
const axisDiff = (a: number, b: number) => {
  const r = Math.abs((((a - b) % Math.PI) + Math.PI) % Math.PI);
  return Math.min(r, Math.PI - r);
};

function rate(items: Generated[], kind: string): { share: number; misses: string[] } {
  const misses: string[] = [];
  for (const g of items) {
    const got = recognize(g.samples)?.shape.kind ?? 'null';
    if (got !== kind) misses.push(`${g.note} → ${got}`);
  }
  return { share: 1 - misses.length / items.length, misses };
}

describe('ovals are ellipses, distinct from circles', () => {
  it('ellipses: centre, radii and axis from the stroke', () => {
    const rng = seeded(351);
    for (let i = 0; i < 24; i++) {
      const g = genEllipse(rng, 1.4 + (i % 8) * 0.2);
      const r = recognize(g.samples);
      if (r?.shape.kind !== 'ellipse') throw new Error(`${g.note}: ${r?.shape.kind}`);
      const [a, b] = g.truth.radii as [number, number];
      expect(d(r.shape.center, g.truth.center as Vec2), g.note).toBeLessThan(2);
      expect(Math.abs(r.shape.majorRadius / a - 1), g.note).toBeLessThan(0.06);
      expect(Math.abs(r.shape.minorRadius / b - 1), g.note).toBeLessThan(0.08);
      expect(axisDiff(r.shape.rotation, g.truth.angle as number), g.note).toBeLessThan(0.08);
      expect(r.shape.majorRadius).toBeGreaterThanOrEqual(r.shape.minorRadius);
      expect(r.confidence).toBeGreaterThan(0.5);
      expect(r.implied).toEqual([]);
    }
  });

  it('circles stay circles; nearly round ovals are never ellipses', () => {
    const rng = seeded(352);
    const circles = Array.from({ length: 20 }, () => genCircle(rng));
    expect(rate(circles, 'circle').misses).toEqual([]);
    for (let i = 0; i < 12; i++) {
      const g = genEllipse(rng, 1.04 + 0.01 * i);
      expect(recognize(g.samples)?.shape.kind, g.note).not.toBe('ellipse');
    }
  });

  it('a shakier hand: ≥ 90% of ovals', () => {
    const items = withPen(SHAKY, () => {
      const rng = seeded(353);
      return Array.from({ length: 30 }, () => genEllipse(rng));
    });
    const { share, misses } = rate(items, 'ellipse');
    expect(share, misses.join('\n')).toBeGreaterThanOrEqual(0.9);
  });
});

describe('smooth strokes are splines', () => {
  it('open waves: a spline through a few evenly spaced points, ends included', () => {
    const rng = seeded(354);
    const items = Array.from({ length: 30 }, () => genWave(rng));
    const { share, misses } = rate(items, 'spline');
    // A smooth stroke that isn't recognised stays a polyline (the conservative fallback).
    expect(share, misses.join('\n')).toBeGreaterThanOrEqual(0.9);
    for (const m of misses) expect(m).toMatch(/→ polyline$/);
    for (const g of items) {
      const r = recognize(g.samples);
      if (r?.shape.kind !== 'spline') continue;
      expect(r.shape.closed).toBe(false);
      expect(r.shape.points.length).toBeGreaterThanOrEqual(4);
      expect(r.shape.points.length).toBeLessThanOrEqual(12);
      const first = g.samples[0] as StrokeSample;
      const last = g.samples[g.samples.length - 1] as StrokeSample;
      expect(d(r.shape.points[0] as Vec2, [first.x, first.y])).toBeLessThan(1e-9);
      const pts = r.shape.points;
      expect(d(pts[pts.length - 1] as Vec2, [last.x, last.y])).toBeLessThan(1e-9);
      // Evenly spaced: consecutive chords within a factor of 2 of each other.
      const chords = pts.slice(1).map((p, k) => d(p, pts[k] as Vec2));
      expect(Math.max(...chords) / Math.min(...chords)).toBeLessThan(2);
      expect(r.confidence).toBeGreaterThan(0.5);
    }
  });

  it('closed blobs: a closed spline', () => {
    const rng = seeded(355);
    const items = Array.from({ length: 20 }, () => genBlob(rng));
    for (const g of items) {
      const r = recognize(g.samples);
      if (r?.shape.kind !== 'spline') throw new Error(`${g.note}: ${r?.shape.kind}`);
      expect(r.shape.closed).toBe(true);
      expect(r.implied).toContain('coincident');
    }
  });

  it('polylines, zigzags, triangles and arcs are not splines', () => {
    const rng = seeded(356);
    const corners = [
      ...Array.from({ length: 15 }, () => genPolyline(rng)),
      ...Array.from({ length: 10 }, () => genZigzag(rng)),
      ...Array.from({ length: 10 }, () => genTriangle(rng)),
    ];
    expect(rate(corners, 'polyline').misses).toEqual([]);
    expect(
      rate(
        Array.from({ length: 15 }, () => genArc(rng)),
        'arc',
      ).misses,
    ).toEqual([]);
  });

  it('a shakier hand: ≥ 75% of waves and blobs (the rest stay polylines)', () => {
    const items = withPen(SHAKY, () => {
      const rng = seeded(357);
      return [
        ...Array.from({ length: 20 }, () => genWave(rng)),
        ...Array.from({ length: 10 }, () => genBlob(rng)),
      ];
    });
    const { share, misses } = rate(items, 'spline');
    expect(share, misses.join('\n')).toBeGreaterThanOrEqual(0.75);
    for (const m of misses) expect(m).toMatch(/→ polyline$/);
  });
});

describe('frozen stroke fixtures', () => {
  for (const f of fixtures as { label: string; note: string; samples: StrokeSample[] }[]) {
    it(`${f.note} → ${f.label}`, () => {
      expect(recognize(f.samples)?.shape.kind).toBe(f.label);
    });
  }
});

describe('strokeFragment for ellipses and splines', () => {
  it('an ellipse stroke becomes a free ellipse (5 DOF) that solves in place', async () => {
    const g = genEllipse(seeded(358), 2);
    const r = recognize(g.samples);
    if (!r) throw new Error('none');
    let n = 0;
    const frag = strokeFragment(r, { id: () => `x${++n}` });
    if (!frag) throw new Error('no fragment');
    const e = frag.entities.find((x) => x.kind === 'ellipse');
    expect(e?.kind === 'ellipse' && e.majorRadius / e.minorRadius).toBeCloseTo(2, 0);
    const res = (await core()).solve({ ...frag, values: {} });
    expect(res.status).toBe('solved');
    expect(res.dof).toBe(5);
  });

  it('a spline stroke becomes a spline through its fit points, held at its knots', async () => {
    const g = genWave(seeded(359));
    const r = recognize(g.samples);
    if (r?.shape.kind !== 'spline') throw new Error('not a spline');
    let n = 0;
    const frag = strokeFragment(r, { id: () => `x${++n}` });
    if (!frag) throw new Error('no fragment');
    const s = frag.entities.find((x) => x.kind === 'bspline');
    if (s?.kind !== 'bspline') throw new Error('no spline');
    expect(s.knots).toBeDefined();
    expect(frag.constraints.filter((c) => c.kind === 'pointOn')).toHaveLength(
      r.shape.points.length - 2,
    );
    const res = (await core()).solve({ ...frag, values: {} });
    expect(res.status).toBe('solved');
    // Through points (2 each) and the two end handles (2 each).
    expect(res.dof).toBe(2 * r.shape.points.length + 4);
    // Nothing moved.
    for (const e of frag.entities) {
      const out = res.entities.find((x) => x.id === e.id);
      if (e.kind === 'point' && out?.kind === 'point') {
        expect(out.x).toBeCloseTo(e.x, 9);
        expect(out.y).toBeCloseTo(e.y, 9);
      }
    }
  });

  it('≤ 2 ms per oval or wave of 500 samples', () => {
    const rng = seeded(360);
    const strokes = [genEllipse(rng), genWave(rng), genBlob(rng)].map((g) => g.samples);
    for (const s of strokes) for (let i = 0; i < 5; i++) recognize(s);
    // Median per stroke, like the other timing tests: one GC pause must not fail the budget.
    const times: number[] = [];
    for (let i = 0; i < 30; i++) {
      const t0 = performance.now();
      recognize(strokes[i % 3] as StrokeSample[]);
      times.push(performance.now() - t0);
    }
    times.sort((a, b) => a - b);
    const median = times[15] as number;
    expect(median).toBeLessThan(process.env.CI ? 6 : 2);
  });
});
